const UI_VERSION='0.2.1';
type User={id:string;username:string;role:string;bulk_allowed?:boolean};
function canBulk(user:User){return user.role==='admin'||(user.role==='operator'&&!!user.bulk_allowed)}
type Job={kind?:'single'|'bulk';id:string;label:string;state:string;environment:string;created:number;total:number;checked:number;pending:number;duplicates:number;counts:Record<string,number>;progress:number;speed:number;message:string};
const statuses:Record<string,string>={found:'Odnaleziono ADE',not_found:'Brak dopasowania',ambiguous:'Wymaga sprawdzenia',invalid:'Dane nieprawidłowe',technical_error:'Błąd techniczny',unauthorized:'Brak uprawnień',pending:'Oczekuje',running:'W toku',unmapped:'Nieprzypisane',needs_review:'Do sprawdzenia',review:'Kontrola operatora'};
const states:Record<string,string>={draft:'Do przygotowania',queued:'W kolejce',running:'W trakcie',paused:'Wstrzymane',cancelled:'Anulowane',completed:'Zakończone',completed_errors:'Zakończone z błędami',blocked:'Zablokowane'};
const fields:Record<string,string>={id:'ID źródłowe',imie:'Imię',nazwisko:'Nazwisko',pesel:'PESEL',ulica:'Ulica',nr_budynku:'Numer budynku',nr_lokalu:'Numer lokalu',kod_pocztowy:'Kod pocztowy',miejscowosc:'Miejscowość',kraj:'Kraj (ISO)'};
const emptyPerson=Object.fromEntries(Object.keys(fields).map(k=>[k,k==='kraj'?'PL':'']));
function jobStatus(job:Job){return job.state==='completed'&&((job.counts.technical_error||0)+(job.counts.unauthorized||0)>0)?'completed_errors':job.state}
function date(t?:number){return t?new Date(t*1000).toLocaleString('pl-PL',{dateStyle:'short',timeStyle:'short'}):'—'}
function number(n:number){return n.toLocaleString('pl-PL')}
const Notice=createContext<(m:string)=>void>(()=>{});
function Badge({status}:{status:string}){return <span className={'badge '+status}><i/>{statuses[status]||states[status]||status}</span>}
function Button({children,onClick,primary=false,disabled=false}:{children:React.ReactNode;onClick:()=>void;primary?:boolean;disabled?:boolean}){return <button type="button" className={primary?'primary':'secondary'} disabled={disabled} onClick={onClick}>{children}</button>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function Modal({title,children,onClose}:{title:string;children:React.ReactNode;onClose:()=>void}){
 const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{ref.current?.showModal()},[]);
 return <dialog ref={ref} onCancel={onClose}><div className="modalhead"><h2>{title}</h2><button className="icon" aria-label="Zamknij" onClick={onClose}><X size={20}/></button></div>{children}</dialog>
}
function Login({onLogin}:{onLogin:(u:User)=>void}){
 const notify=useContext(Notice);const [name,N]=useState(''),[pass,P]=useState(''),[code,C]=useState(''),[busy,B]=useState(false),[secret,S]=useState('');
 async function submit(enroll=false){B(true);try{if(enroll){const r=await api('/auth/enroll','POST',{username:name,password:pass,code:secret?code:''});if(r.secret)S(r.secret);else{S('');notify('MFA aktywne. Zaloguj się kodem z aplikacji.')}}else{const u=await api('/auth/login','POST',{username:name,password:pass,code});setCsrf(u.csrf);onLogin(u)}}catch(e){notify((e as Error).message)}finally{B(false)}}
 return <div className="login"><div className="login-intro"><div className="login-brand"><div className="brand-icon"><ShieldCheck size={27}/></div><strong>BAE <span>Weryfikator</span></strong></div><div className="login-copy"><div className="eyebrow">BAZA ADRESÓW ELEKTRONICZNYCH</div><h2>Weryfikacja adresów<br/>do e-Doręczeń.</h2><p>Sprawdź osobę lub przygotuj weryfikację całej listy adresatów.</p><div className="login-features"><span><UserRoundSearch size={19}/> Wyszukiwanie pojedyncze</span><span><Files size={19}/> Import CSV i JSON</span><span><ShieldCheck size={19}/> Dostęp chroniony przez MFA</span></div></div><div className="login-emblem" aria-hidden="true"><ShieldCheck strokeWidth={.7}/></div></div><div className="login-panel"><form onSubmit={e=>{e.preventDefault();submit()}}><div className="eyebrow">DOSTĘP DLA UPOWAŻNIONYCH OSÓB</div><h1>Zaloguj się</h1><p>Weryfikacja adresów do e-Doręczeń</p><Field label="Login"><input autoComplete="username" value={name} onChange={e=>N(e.target.value)} required/></Field><Field label="Hasło"><input type="password" autoComplete="current-password" value={pass} onChange={e=>P(e.target.value)} required/></Field>{secret&&<div className="notice"><strong>Dodaj klucz do aplikacji uwierzytelniającej</strong><code>{secret}</code><span>Po wpisaniu kodu wybierz „Potwierdź MFA”. Klucz jest pokazywany tylko podczas aktywacji.</span></div>}<Field label="Kod MFA"><input inputMode="numeric" autoComplete="one-time-code" value={code} maxLength={6} onChange={e=>C(e.target.value)}/></Field><button type="submit" disabled={busy} className="primary full">Zaloguj się <ArrowRight size={17}/></button><button type="button" className="textbutton" disabled={busy} onClick={()=>submit(true)}>{secret?'Potwierdź MFA':'Pierwsze logowanie — aktywuj MFA'}</button></form><span className="login-audit muted"><ShieldCheck size={15}/> Dostęp jest rejestrowany w dzienniku audytowym.</span></div></div>
}
const nav=[{id:'dashboard',name:'Pulpit',icon:LayoutDashboard},{id:'person',name:'Sprawdź osobę',icon:UserRoundSearch},{id:'import',name:'Weryfikacja masowa',icon:Files},{id:'results',name:'Wyniki',icon:Table2},{id:'history',name:'Historia zadań',icon:History},{id:'reports',name:'Raporty',icon:ChartNoAxesCombined},{id:'admin',name:'Administracja',icon:ShieldCheck},{id:'settings',name:'Ustawienia',icon:Settings}];
function App(){
 const [user,U]=useState<User|null>(null),[loaded,L]=useState(false),[page,P]=useState('dashboard'),[jobs,J]=useState<Job[]>([]),[connection,C]=useState<any>(null),[chosen,S]=useState(''),[message,M]=useState(''),[mobile,B]=useState(false),[recordFilter,RF]=useState(''),[jobFilter,JF]=useState('');
 function notify(m:string){M(m)}
 useEffect(()=>{api('/auth/me').then(u=>{setCsrf(u.csrf);U(u)}).catch(()=>{}).finally(()=>L(true))},[]);
 async function refresh(){try{const [j,c]=await Promise.all([api('/jobs?size=100'),api('/connection')]);J(j.items);C(c)}catch(e){notify((e as Error).message)}}
 useEffect(()=>{if(user){refresh();const timer=setInterval(refresh,15000);return()=>clearInterval(timer)}},[user]);
 useEffect(()=>{if(message){const t=setTimeout(()=>M(''),8000);return()=>clearTimeout(t)}},[message]);
 useEffect(()=>{if(!mobile)return;const close=(e:KeyboardEvent)=>{if(e.key==='Escape')B(false)};const previous=document.body.style.overflow;document.body.style.overflow='hidden';document.addEventListener('keydown',close);return()=>{document.body.style.overflow=previous;document.removeEventListener('keydown',close)}},[mobile]);
 function navigate(p:string){P(p);B(false)}
 function openJob(id:string,status=''){S(id);JF(status);navigate('results');refresh()}
 function openRecords(status:string){RF(status);navigate('records')}
 if(!loaded)return <div className="loading">Uruchamianie panelu…</div>;
 return <Notice.Provider value={notify}>{!user?<Login onLogin={U}/>:<div className="shell"><a href="#content" className="skip">Przejdź do treści</a><button className={mobile?'menu-backdrop visible':'menu-backdrop'} aria-label="Zamknij menu" tabIndex={mobile?0:-1} onClick={()=>B(false)}/><aside id="main-menu" className={mobile?'open':''}><div className="brand"><div className="brand-icon"><ShieldCheck size={25}/></div><div><strong>BAE</strong><span>Weryfikator</span></div><button className="icon sidebar-close" aria-label="Zamknij menu" onClick={()=>B(false)}><X size={20}/></button></div><div className="navlabel">OBSZAR ROBOCZY</div><nav aria-label="Menu główne">{nav.filter(n=>user.role==='admin'||n.id!=='admin').filter(n=>user.role!=='auditor'||!['person','import'].includes(n.id)).filter(n=>n.id!=='import'||canBulk(user)).map(n=><button key={n.id} className={(page===n.id||(page==='records'&&n.id==='results'))?'active':''} aria-current={(page===n.id||(page==='records'&&n.id==='results'))?'page':undefined} onClick={()=>navigate(n.id)}><n.icon size={19}/><span>{n.name}</span>{n.id==='history'&&<small>{jobs.length}</small>}</button>)}</nav><div className="sidebar-bottom"><div className="secure"><Shield size={18}/><div><strong>Dane chronione</strong><span>Dostęp zgodny z uprawnieniami</span></div></div><div className="profile"><div className="avatar">{user.username.slice(0,2).toUpperCase()}</div><div><strong>{user.username}</strong><span>{{admin:'Administrator',operator:'Operator',auditor:'Audytor'}[user.role]}</span></div><button aria-label="Wyloguj się" title="Wyloguj się" className="icon" onClick={async()=>{try{await api('/auth/logout','POST');U(null);setCsrf('')}catch(e){notify((e as Error).message)}}}><LogOut size={17}/></button></div></div></aside><div className="workspace"><header><button className="icon mobile-toggle" aria-label="Menu" aria-expanded={mobile} aria-controls="main-menu" onClick={()=>B(!mobile)}><Menu size={22}/></button><span>Panel weryfikacji <ChevronRight size={14}/> <strong>{(page==='records'?'Wszystkie rekordy':nav.find(n=>n.id===page)?.name)}</strong></span><div className="header-right"><span className={'env '+(connection?.environment==='PROD'?'prod':'')}>{connection?.environment||'INT'}</span><span className={connection?.ready?'status-dot ready':'status-dot'}/><span>{connection?.ready?'Połączenie skonfigurowane':'BAE nieskonfigurowane'}</span><div className="header-avatar">{user.username.slice(0,1).toUpperCase()}</div></div></header><main id="content"><div className="page-heading"><div><div className="eyebrow">BAZA ADRESÓW ELEKTRONICZNYCH</div><h1>{(page==='records'?'Wszystkie rekordy':nav.find(n=>n.id===page)?.name)}</h1><p>{{dashboard:'Przegląd weryfikacji adresów do e-Doręczeń.',person:'Sprawdź adres ADE wskazanej osoby.',import:'Zaimportuj dane i przygotuj zadanie weryfikacji.',records:'Rekordy ze wszystkich dostępnych zadań.',results:'Przeglądaj, poprawiaj i eksportuj wyniki.',history:'Zadania weryfikacji i historia operacji.',reports:'Przygotuj zestawienie do dalszej obsługi korespondencji.',admin:'Połączenie z BAE, użytkownicy i retencja.',settings:'Ustawienia interfejsu i informacje o aplikacji.'}[page]}</p></div>{page==='dashboard'&&user.role!=='auditor'&&<Button primary onClick={()=>navigate('person')}><Plus size={18}/> Nowa weryfikacja</Button>}</div>
 {!connection?.ready&&<div className="connection-notice"><div className="notice-icon"><LockKeyhole size={19}/></div><div><strong>Dostęp do BAE wymaga konfiguracji</strong><p>Import i przygotowanie danych są dostępne. Sprawdzanie wymaga uprawnień urzędu, certyfikatu i klucza systemu.</p></div>{user.role==='admin'&&<button className="textbutton" onClick={()=>navigate('admin')}>Skonfiguruj połączenie <ArrowRight size={16}/></button>}</div>}
 {page==='dashboard'&&<Dashboard jobs={jobs} user={user} openJob={openJob} openRecords={openRecords} navigate={navigate}/>}
 {page==='person'&&<PersonForm openJob={openJob} ready={!!connection?.ready}/>}
 {page==='import'&&canBulk(user)&&<Importer openJob={openJob} refresh={refresh}/>}
 {page==='records'&&<Records key={recordFilter} initialStatus={recordFilter} openJob={openJob}/>}
 {page==='results'&&<Results key={chosen+jobFilter} initialStatus={jobFilter} id={chosen} setId={S} jobs={jobs} user={user} refresh={refresh}/>}
 {page==='history'&&<><JobList openJob={openJob}/>{user.role==='admin'&&<ActivityReport/>}<AuditLog/></>}
 {page==='reports'&&<Reports jobs={jobs} openJob={openJob}/>}
 {page==='admin'&&<Administration refresh={refresh} userId={user.id}/>}
 {page==='settings'&&<SettingsView/>}
 <footer><span>BAE Weryfikator <span className="muted">UI {UI_VERSION}</span></span><span><ShieldCheck size={14}/> Dostęp rejestrowany · Dane szyfrowane</span></footer></main></div></div>}{message&&<div className="toast" role="alert"><AlertTriangle size={19}/><span>{message}</span><button className="icon" aria-label="Zamknij komunikat" onClick={()=>M('')}><X size={16}/></button></div>}</Notice.Provider>
}
function Dashboard({jobs,user,openJob,openRecords,navigate}:{jobs:Job[];user:User;openJob:(id:string)=>void;openRecords:(status:string)=>void;navigate:(p:string)=>void}){
 const [stats,S]=useState<any>(null);useEffect(()=>{api('/stats').then(S).catch(()=>{})},[jobs]);
 const counts=stats?.counts||{};const total=stats?.total||0;const checked=Object.entries(counts).filter(([k])=>!['pending','running'].includes(k)).reduce((n,[,v])=>n+Number(v),0);
 return <><div className="stats">{[{filter:'',name:'Wszystkie rekordy',n:total,icon:Files,sub:'W dostępnych zadaniach',tone:'navy'},{filter:'found',name:'Odnaleziono ADE',n:counts.found||0,icon:CheckCircle2,sub:'Aktywny adres do e-Doręczeń',tone:'green'},{filter:'not_found',name:'Brak dopasowania',n:counts.not_found||0,icon:Search,sub:'Wymaga oceny dalszego trybu',tone:'gray'},{filter:'needs_review',name:'Do sprawdzenia',n:stats?.needs_review??((counts.invalid||0)+(counts.ambiguous||0)+(counts.technical_error||0)+(counts.unauthorized||0)),icon:AlertTriangle,sub:'Błędy i ręczna kontrola',tone:'amber'}].map(s=><button type="button" className={'stat '+s.tone} key={s.name} onClick={()=>openRecords(s.filter)} aria-label={s.name+' — pokaż rekordy'}><div><span>{s.name}</span><s.icon size={20}/></div><strong>{number(s.n)}</strong><small>{s.sub}</small></button>)}</div>
 {user.role!=='auditor'&&<div className="quick-actions"><button onClick={()=>navigate('person')}><div className="quick-icon"><UserRoundSearch size={23}/></div><div><strong>Sprawdź jedną osobę</strong><span>Wyszukiwanie po PESEL lub adresie</span></div><ArrowRight size={19}/></button>{canBulk(user)&&<button onClick={()=>navigate('import')}><div className="quick-icon"><Upload size={23}/></div><div><strong>Weryfikacja z pliku</strong><span>Import CSV lub JSON · do 100 000 rekordów</span></div><ArrowRight size={19}/></button>}</div>}
 <div className="dashboard-grid"><section className="card"><div className="cardhead"><div><h2>Ostatnie zadania</h2><p>Najnowsze importy i sprawdzenia</p></div><button className="textbutton" onClick={()=>navigate('history')}>Wszystkie zadania <ArrowRight size={15}/></button></div><JobsTable jobs={jobs.slice(0,5)} openJob={openJob}/></section><section className="card breakdown"><div className="cardhead"><div><h2>Postęp weryfikacji</h2><p>W dostępnych zadaniach</p></div></div><div className="donut" role="img" aria-label={`${total?Math.round(checked/total*100):0}% zakończonych, ${checked} z ${total} rekordów`} style={{'--pct':`${total?checked/total*100:0}%`} as React.CSSProperties}><div><strong>{total?Math.round(checked/total*100):0}%</strong><span>zakończonych</span></div></div><div className="legend"><span><i className="green-dot"/>Sprawdzone</span><strong>{number(checked)}</strong><span><i/>Oczekujące</span><strong>{number(Math.max(total-checked,0))}</strong></div></section></div>
 <div className="info-strip"><ShieldCheck size={22}/><div><strong>Każde sprawdzenie ma ślad w historii</strong><span>Wynik zawiera czas i źródło weryfikacji. Brak dopasowania wymaga oceny operatora przed wyborem kanału doręczenia.</span></div><button className="textbutton" onClick={()=>navigate('history')}>Historia operacji <ArrowRight size={16}/></button></div></>
}
function Records({initialStatus,openJob}:{initialStatus:string;openJob:(id:string,status?:string)=>void}){
 const notify=useContext(Notice),[status,T]=useState(initialStatus),[page,P]=useState(1),[q,Q]=useState(''),[search,S]=useState(''),[data,D]=useState<any>({items:[],total:0}),[busy,B]=useState(false),[revision,R]=useState(0),[review,REV]=useState<any>(null);
 useEffect(()=>{let alive=true;const controller=new AbortController();async function load(){B(true);try{const response=await fetch(`/api/records?page=${page}&status=${status}&q=${encodeURIComponent(search)}`,{credentials:'same-origin',signal:controller.signal});if(!response.ok)throw new Error('Nie udało się pobrać rekordów (HTTP '+response.status+')');const result=await response.json();if(alive)D(result)}catch(e){if(alive)notify((e as Error).message)}finally{if(alive)B(false)}}load();const timer=setInterval(load,15000);return()=>{alive=false;controller.abort();clearInterval(timer)}},[page,status,search,revision]);
 return <section className="card"><div className="cardhead"><div><h2>{status==='needs_review'?'Do sprawdzenia':statuses[status]||'Wszystkie rekordy'}</h2><p>Wszystkie dostępne zadania · {number(data.total)} rekordów</p></div><span className="muted" role="status">{busy?'Pobieranie…':'Odświeżanie co 15 s'}</span></div><div className="table-toolbar"><div className="filter"><select aria-label="Filtr rekordów" value={status} onChange={e=>{T(e.target.value);P(1)}}><option value="">Wszystkie statusy</option>{Object.entries(statuses).filter(([k])=>k!=='review').map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></div><form className="searchbox" onSubmit={e=>{e.preventDefault();S(q);P(1)}}><Search size={17}/><input aria-label="Wyszukiwanie rekordów" placeholder="Dokładny PESEL, ID lub imię i nazwisko" value={q} onChange={e=>Q(e.target.value)}/><button className="icon" aria-label="Szukaj"><ArrowRight size={16}/></button></form><Button onClick={()=>R(revision+1)}><RefreshCw size={16}/>Odśwież</Button></div><div className="tablewrap"><table className="records-table" aria-busy={busy}><thead><tr><th>Zadanie / wiersz</th><th>ID</th><th>Imię i nazwisko</th><th>PESEL</th><th>Status</th><th>ADE</th><th>Sprawdzono</th><th>Uwagi</th><th>Opcje</th></tr></thead><tbody>{data.items.map((r:any)=><tr key={r.row_id}><td><strong>{r.job_label}</strong><small className="record-origin">{r.environment} · {r.job_id.slice(0,8)} · wiersz {r.position}</small></td><td>{r.id||'—'}</td><td className="nowrap">{r.imie} {r.nazwisko}{r.encoding_repairs?.length>0&&<small className="review-label" title={r.encoding_repairs.join(' · ')}>Naprawiono kodowanie</small>}{r.review&&<small className="review-label">Do kontroli operatora</small>}</td><td className="mono nowrap">{r.pesel||'—'}</td><td><Badge status={r.status}/></td><td className="mono">{r.ade||'—'}</td><td className="nowrap">{date(r.checked)}</td><td className="notes">{r.note||r.operator_note||'—'}{(r.status==='ambiguous'||r.review)&&<button type="button" className="textbutton" onClick={()=>REV(r)}>Powód kontroli</button>}</td><td><button type="button" className="textbutton" onClick={()=>openJob(r.job_id,status)}>Otwórz zadanie <ArrowRight size={14}/></button></td></tr>)}</tbody></table>{!busy&&!data.items.length&&<div className="empty"><Table2 size={28}/><p>Brak rekordów pasujących do filtrów.</p></div>}</div><Pager page={page} size={25} total={data.total} change={P}/>{review&&<ReviewDetails row={review} onClose={()=>REV(null)}/>}</section>
}
function JobsTable({jobs,openJob}:{jobs:Job[];openJob:(id:string)=>void}){return jobs.length?<div className="tablewrap"><table><thead><tr><th>Nazwa zadania</th><th>Rekordy</th><th>Status</th><th>Utworzono</th><th><span className="sr-only">Otwórz</span></th></tr></thead><tbody>{jobs.map(j=><tr key={j.id}><td><button className="jobname" onClick={()=>openJob(j.id)}><FileSpreadsheet size={19}/><span><strong>{j.label}</strong><small>{j.environment} · {j.id.slice(0,8)}</small></span></button></td><td>{number(j.total)}</td><td><Badge status={jobStatus(j)}/>{j.state==='running'&&<progress aria-label="Postęp zadania" value={j.progress} max={100}/>}</td><td className="muted nowrap">{date(j.created)}</td><td><button className="icon" aria-label={'Otwórz '+j.label} onClick={()=>openJob(j.id)}><ChevronRight size={17}/></button></td></tr>)}</tbody></table></div>:<div className="empty"><Files size={33}/><h3>Brak zadań</h3><p>Po zaimportowaniu pliku lub sprawdzeniu osoby zobaczysz tutaj postęp i wyniki.</p></div>}
function JobList({openJob}:{openJob:(id:string)=>void}){const [page,P]=useState(1),[data,D]=useState<any>({items:[],total:0});useEffect(()=>{api('/jobs?page='+page).then(D)},[page]);return <section className="card"><JobsTable jobs={data.items} openJob={openJob}/><Pager page={page} size={20} total={data.total} change={P}/></section>}
function PersonFields({p,set,method,disabled=false}:{p:any;set:(p:any)=>void;method:string;disabled?:boolean}){let names=method==='pesel'?['imie','nazwisko','pesel']:['imie','nazwisko','ulica','nr_budynku','nr_lokalu','kod_pocztowy','miejscowosc','kraj'];return <div className="formgrid">{names.map(k=><Field key={k} label={fields[k]+(k==='nr_lokalu'||k==='ulica'?' (opcjonalnie)':' *')}><input required={!['nr_lokalu','ulica'].includes(k)} value={p[k]||''} onChange={e=>set({...p,[k]:e.target.value})} disabled={disabled} maxLength={k==='pesel'?11:k==='kraj'?2:undefined} inputMode={k==='pesel'?'numeric':undefined} autoComplete="off"/></Field>)}</div>}
